        return 0;
    errno = 0;
    unsigned long long n = strtoull(s, &end, 10);
    if (errno)
        return 0;

    unsigned long long mult = 1;
    switch (*end) {
    case 'g':
    case 'G':
        mult = 1024ULL * 1024 * 1024;
        end++;
        break;
    case 'm':
    case 'M':
        mult = 1024ULL * 1024;
        end++;
        break;
    case 'k':
    case 'K':
        mult = 1024;
        end++;
        break;
